import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './Badge.module.css'

export interface BadgeProps extends Omit<ComponentProps<'span'>, 'children'> {
  count?: number
  variant?: 'primary' | 'accent' | 'secondary' | 'destructive' | 'success' | 'warning'
  size?: 'sm' | 'md'
  /** A dot with no number: "something new", not "how many". */
  isDot?: boolean
  /** Counts above this show as `maxCount+`. */
  maxCount?: number
  /** Pins the badge to a corner of `children` instead of sitting inline. */
  isFloating?: boolean
  floatingPlacement?: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end'
  /** The element a floating badge is pinned to. */
  children?: ReactNode
}

export function Badge({
  count,
  variant = 'primary',
  size = 'md',
  isDot = false,
  maxCount,
  isFloating = false,
  floatingPlacement = 'top-end',
  children,
  className,
  ...props
}: BadgeProps) {
  const hasBadge = isDot || count !== undefined
  const badge = hasBadge && (
    <span
      // A labelled badge is an image of a state: a plain span may not carry
      // aria-label. An unlabelled dot says nothing, and a floating badge sits
      // outside the element it describes, so both are hidden — the meaning
      // belongs in the anchor's own name.
      role={props['aria-label'] ? 'img' : undefined}
      aria-hidden={!props['aria-label'] && (isDot || isFloating) ? true : undefined}
      className={cn(
        styles.badge,
        styles[variant],
        styles[size],
        isDot && styles.dot,
        isFloating && [styles.floating, styles[floatingPlacement]],
        className,
      )}
      {...props}
    >
      {isDot ? null : maxCount !== undefined && count! > maxCount ? `${maxCount}+` : count}
    </span>
  )

  if (children === undefined) return badge
  return (
    <span className={styles.anchor}>
      {children}
      {badge}
    </span>
  )
}

.anchor {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

/* Always a pill, whatever the Theme's radius preset: a squared-off count
   reads as a key cap, not a badge. 9999px is the usual "fully round". */
.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  box-sizing: border-box;
  border-radius: 9999px;
  font-family: var(--font-sans);
  font-size: var(--text-body-xs);
  line-height: var(--leading-body-xs);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 16px at sm, 20px at md, in em so the Theme's scaling carries them.
   min-inline-size equal to the height keeps a single digit a circle
   rather than an oval. */
.sm {
  block-size: 1.6em;
  min-inline-size: 1.6em;
  padding-inline: 0.125rem;
}

.md {
  block-size: 2em;
  min-inline-size: 2em;
  padding-inline: var(--space-1);
}

.dot {
  min-inline-size: 0;
  padding: 0;
  inline-size: var(--space-2);
  block-size: var(--space-2);
}

.dot.sm {
  inline-size: var(--space-1-5);
  block-size: var(--space-1-5);
}

.primary {
  background: var(--primary);
  color: var(--primary-foreground);
}

/* The token set has one brand hue, so accent is the inverted neutral: the
   strongest contrast available without inventing a colour. */
.accent {
  background: var(--foreground);
  color: var(--background);
}

.secondary {
  background: var(--secondary);
  color: var(--secondary-foreground);
}

/* A dot has no text to carry it, so it must reach 3:1 against the page on
   its own; the secondary fill is far below that. */
.dot.secondary {
  background: var(--muted-foreground);
}

.destructive {
  background: var(--destructive);
  color: var(--destructive-foreground);
}

/* Status colours, for presence and state dots: success is Online, warning
   Away or Pending. Offline is secondary; info would repeat primary's blue. */
.success {
  background: var(--success);
  color: var(--success-foreground);
}

.warning {
  background: var(--warning);
  color: var(--warning-foreground);
}

/* Same 3:1 rule as the secondary dot: amber-500 reaches only 2:1 on the
   light page, so the dot steps down to amber-600. */
.dot.warning {
  background: var(--warning-indicator);
}

/* The ring in the page background separates the badge from whatever it
   overlaps, so it reads on top of an icon or avatar of any colour. 2px is
   the same width as the focus ring: enough to read as a gap, not a border. */
.floating {
  position: absolute;
  box-shadow: 0 0 0 2px var(--background);
}

/* start/end are physical left/right, so RTL pages get mirrored
   placement. Add [dir='rtl'] overrides when an RTL consumer appears; not
   :dir(rtl), which the build lowers to a :lang() list (see Switch). */
.top-start {
  top: 0;
  left: 0;
  translate: -50% -50%;
}

.top-end {
  top: 0;
  right: 0;
  translate: 50% -50%;
}

.bottom-start {
  bottom: 0;
  left: 0;
  translate: -50% 50%;
}

.bottom-end {
  bottom: 0;
  right: 0;
  translate: 50% 50%;
}
